#!/usr/bin/env node
/**
 * Import leads from PR Freelance pipeline scrape 2026-06-15
 *
 * Usage:  cd MarCRM && node scripts/import-pr-freelance-2026-06-15.cjs
 *
 * - All leads have pipeline="pr-freelance"
 * - Deduplicates by company name (skips if already in DB)
 * - Creates Company + Contact records, logs a ScrapeResult for each lead
 * - Populates enhanced freelance fields: vertical, subvertical, engagementModel,
 *   buyerType, compensationText, remoteFlag, employmentTypeRaw, urgencyScore
 *
 * NOTE: Neon DB is unreachable from the Cowork sandbox, so this script
 * is generated by the scrape but must be run from Katie's local machine
 * where DATABASE_URL points to the Neon production instance.
 */

const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

const LEADS = [
  // ─── 1. The Work Crowd (theworkcrowd.com) — IR/financial-comms marketplace — combined 80, A ───
  {
    company: {
      name: "The Work Crowd (theworkcrowd.com)",
      website: "https://theworkcrowd.com",
      pipeline: "pr-freelance",
      industry: "Freelance/interim marketing, PR, communications & IR marketplace (UK-based, global network)",
      size: "Marketplace / talent network",
      location: "Remote (UK / EU / global)",
      fundingStage: "Marketplace / talent network",
      techStack: JSON.stringify([
        "investor relations",
        "financial communications",
        "media relations",
        "thought leadership / content",
        "freelance / interim / fractional",
      ]),
      fitScore: 50,
      intentScore: 30,
      fitDetails: JSON.stringify({ pr_remit: 20, sector_fit: 15, workstream: 10, buyer_quality: 5, urgency: 0 }),
      intentDetails: JSON.stringify({ engagement_model: 15, remote_flex: 10, recency: 0, urgency_signals: 0, apply_path: 5 }),
      vertical: "pr",
      subvertical: "investor-pr",
      engagementModel: "freelance",
      buyerType: "agency",
      compensationText: "Varies by brief; UK jobs board postings observed in the £150-£1,500 day-rate range",
      remoteFlag: "remote",
      employmentTypeRaw: "Freelance / Interim / Fractional (marketplace + jobs board)",
      urgencyScore: 30,
      starred: true,
      notes: "Combined 80, A. Best sector fit of the run and new to this pipeline: a freelance/interim marketing-comms marketplace with a DEDICATED investor-relations & financial-communications vertical (serves investment banks, corporate finance teams, capital markets divisions on financial reporting and shareholder communications) plus a broader jobs board covering PR & comms, content/thought leadership, public affairs. ACTION: register Mark as a freelancer, emphasizing IR/financial-communications experience, and set alerts on the general PR & comms / content / thought-leadership board. Marketplace/platform (not a single dated posting) so recency scored 0.",
      source: "PR Freelance Scrape 2026-06-15",
      lastActivity: "Register as freelancer — IR/financial-communications vertical",
    },
    contacts: [
      { name: "The Work Crowd — Customer Success / Freelancer Onboarding", title: "Talent network", persona: "Recruiting", decisionMaker: false, email: "hello@theworkcrowd.com", linkedin: "https://www.linkedin.com/company/theworkcrowd" },
    ],
    scrape: {
      url: "https://theworkcrowd.com/hire-investor-relations-consultants",
      source: "websearch",
      matchedSignals: JSON.stringify([
        "dedicated_investor_relations_vertical",
        "financial_communications_explicit",
        "active_jobs_board_pr_and_comms",
        "freelance_interim_fractional",
        "remote_global",
        "registration_apply_path",
      ]),
    },
  },

  // ─── 2. ISTE Live 26 — Senior PR Consultant & Press Secretary (via The Work Crowd) — combined 60, B ───
  {
    company: {
      name: "ISTE Live 26 — Senior PR Consultant & On-Site Press Secretary (via The Work Crowd)",
      website: "https://theworkcrowd.com/jobs/senior-pr-consultant-press-secretary-iste-live-26",
      pipeline: "pr-freelance",
      industry: "EdTech (K-12/higher-ed technology) — conference media relations",
      size: "Operating company (direct client, via The Work Crowd marketplace)",
      location: "Remote prep + on-site Orlando, FL, USA (1-2 days)",
      fundingStage: "Operating company (direct client, via The Work Crowd marketplace)",
      techStack: JSON.stringify([
        "media relations",
        "crisis / reactive messaging",
        "executive briefing (C-suite)",
        "embargo / exclusives management",
        "press kit management",
      ]),
      fitScore: 30,
      intentScore: 30,
      fitDetails: JSON.stringify({ pr_remit: 20, sector_fit: 0, workstream: 10, buyer_quality: 0, urgency: 0 }),
      intentDetails: JSON.stringify({ engagement_model: 15, remote_flex: 0, recency: 0, urgency_signals: 10, apply_path: 5 }),
      vertical: "pr",
      subvertical: "media-relations",
      engagementModel: "freelance",
      buyerType: "operating-company",
      compensationText: "USD $150-$755 day-rate range",
      remoteFlag: "onsite",
      employmentTypeRaw: "Freelance / contract, short-term (<1 week, event-based)",
      urgencyScore: 75,
      starred: false,
      notes: "Combined 60, B. Posted 2026-06-05, updated 2026-06-12 (via The Work Crowd). Freelance Senior PR Consultant to act as on-site 'Press Secretary' for ISTE Live 26 (EdTech's flagship conference): owns media schedule, briefs C-suite for interviews, manages on/off-record ground rules with journalists, drafts crisis/reactive messaging (AI in education, data privacy, screen time), manages embargoes/exclusives. Short-term (<1 week), remote prep + 1-2 days on-site Orlando FL, $150-$755/day. STRONG workstream match (media relations + crisis/executive comms = near-perfect skills showcase for Mark's 'strategic + executional' positioning), but SECTOR is Education/EdTech (not finance/legal/PE-VC/B2B SaaS core ICP) and requires on-site Orlando travel. Included as a stretch/portfolio lead at the 55+ threshold (60, B). ACTION: evaluate logistics fit; if workable, strong case-study opportunity for crisis/media-relations under pressure.",
      source: "PR Freelance Scrape 2026-06-15",
      lastActivity: "Evaluate logistics, apply via The Work Crowd if workable",
    },
    contacts: [
      { name: "The Work Crowd — Job Application", title: "Apply via marketplace", persona: "Hiring", decisionMaker: false, email: "", linkedin: "" },
    ],
    scrape: {
      url: "https://theworkcrowd.com/jobs/senior-pr-consultant-press-secretary-iste-live-26",
      source: "websearch",
      matchedSignals: JSON.stringify([
        "media_relations_and_crisis_comms",
        "executive_briefing_csuite",
        "short_term_event_based_contract",
        "direct_apply_path",
        "sector_mismatch_edtech",
        "onsite_required_orlando",
      ]),
    },
  },
];

async function main() {
  console.log(`\nPR Freelance import 2026-06-15 — ${LEADS.length} leads\n`);
  let created = 0;
  let skipped = 0;

  for (const lead of LEADS) {
    const existing = await prisma.company.findFirst({
      where: { name: lead.company.name },
    });

    if (existing) {
      console.log(`  SKIP  (exists)  ${lead.company.name}`);
      skipped++;
      continue;
    }

    const company = await prisma.company.create({
      data: {
        ...lead.company,
        contacts: {
          create: lead.contacts.map((c) => ({
            name: c.name,
            title: c.title,
            persona: c.persona,
            decisionMaker: c.decisionMaker,
            email: c.email || "",
            linkedin: c.linkedin,
          })),
        },
        scrapeResults: {
          create: [
            {
              pipeline: "pr-freelance",
              url: lead.scrape.url,
              source: lead.scrape.source,
              matchedSignals: lead.scrape.matchedSignals,
              scrapeDate: new Date("2026-06-15"),
            },
          ],
        },
      },
    });

    console.log(`  CREATE          ${company.name}  (fit ${lead.company.fitScore} / intent ${lead.company.intentScore})`);
    created++;
  }

  console.log(`\nDone. Created ${created}, skipped ${skipped}.\n`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
